package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)

	st := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &st[i])
	}

	adj := make([][]int, n)
	adjr := make([][]int, n)
	for i := 0; i < m; i++ {
		var u, v int
		fmt.Fscan(reader, &u, &v)
		u--
		v--
		adj[u] = append(adj[u], v)
		adjr[v] = append(adjr[v], u)
	}

	mark := make([]bool, n)
	ans := make([]int, n)

	for i := 0; i < n; i++ {
		if !mark[i] && st[i] == 1 {
			stack := []int{i}
			for len(stack) > 0 {
				x := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				if mark[x] {
					continue
				}
				mark[x] = true
				ans[x]++
				for _, u := range adj[x] {
					if !mark[u] {
						stack = append(stack, u)
					}
				}
			}
		}
	}

	for i := 0; i < n; i++ {
		mark[i] = false
	}

	for i := 0; i < n; i++ {
		if !mark[i] && st[i] == 2 {
			stack := []int{i}
			for len(stack) > 0 {
				x := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				if mark[x] {
					continue
				}
				mark[x] = true
				ans[x]++
				if st[x] == 1 {
					continue
				}
				for _, u := range adjr[x] {
					if !mark[u] {
						stack = append(stack, u)
					}
				}
			}
		}
	}

	for i := 0; i < n; i++ {
		if ans[i] == 2 {
			fmt.Fprintln(writer, 1)
		} else {
			fmt.Fprintln(writer, 0)
		}
	}
}

